import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import '../features/assets/assets.dart';import '../features/auth/login_screen.dart';import '../features/dashboard/dashboard_screen.dart';import '../features/maintenance/maintenance.dart';import '../features/notifications/notifications_screen.dart';import '../features/profile/profile_screen.dart';import '../features/work_orders/work_orders.dart';import 'app_scaffold.dart';import 'providers.dart';import 'theme.dart';
final routerProvider=Provider<GoRouter>((ref){final auth=ref.watch(authControllerProvider);return GoRouter(initialLocation:'/dashboard',errorBuilder:(c,s)=>const Scaffold(body:Center(child:Text('The requested page is not available.'))),redirect:(c,s){final protected=s.matchedLocation!='/login';if(auth.phase==AuthPhase.starting)return'/startup';if(auth.phase!=AuthPhase.authenticated&&protected&&s.matchedLocation!='/startup')return'/login';if(auth.phase==AuthPhase.authenticated&&!protected)return'/dashboard';return null;},routes:[GoRoute(path:'/startup',builder:(c,s)=>StartupScreen(state:auth)),GoRoute(path:'/login',builder:(c,s)=>const LoginScreen()),ShellRoute(builder:(c,s,child)=>AppScaffold(child:child),routes:[GoRoute(path:'/dashboard',builder:(c,s)=>const DashboardScreen()),GoRoute(path:'/work-orders',builder:(c,s)=>const WorkOrderListScreen(),routes:[GoRoute(path:'create',builder:(c,s)=>const WorkOrderCreateScreen()),GoRoute(path:':uuid',builder:(c,s)=>WorkOrderDetailScreen(s.pathParameters['uuid']!))]),GoRoute(path:'/assets',builder:(c,s)=>const AssetListScreen(),routes:[GoRoute(path:'scan',builder:(c,s)=>const AssetScannerScreen()),GoRoute(path:':uuid',builder:(c,s)=>AssetDetailScreen(s.pathParameters['uuid']!))]),GoRoute(path:'/maintenance',builder:(c,s)=>const MaintenanceListScreen(),routes:[GoRoute(path:':uuid',builder:(c,s)=>MaintenanceDetailScreen(s.pathParameters['uuid']!))]),GoRoute(path:'/notifications',builder:(c,s)=>const NotificationsScreen()),GoRoute(path:'/profile',builder:(c,s)=>const ProfileScreen())])]);});
class SnsuFmoApp extends ConsumerWidget{const SnsuFmoApp({super.key});@override Widget build(BuildContext c,WidgetRef ref)=>MaterialApp.router(title:'SNSU FMO',debugShowCheckedModeBanner:false,theme:AppTheme.light(),routerConfig:ref.watch(routerProvider));}
class StartupScreen extends ConsumerWidget{const StartupScreen({required this.state,super.key});final AuthState state;@override Widget build(BuildContext c,WidgetRef ref)=>Scaffold(body:Center(child:state.phase==AuthPhase.starting?const CircularProgressIndicator():Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.cloud_off_outlined,size:52),const SizedBox(height:16),Text(state.phase==AuthPhase.maintenance?'The system is temporarily under maintenance.':state.message??'Online validation is required.',textAlign:TextAlign.center),const SizedBox(height:16),FilledButton(onPressed:()=>ref.read(authControllerProvider.notifier).restore(),child:const Text('Retry'))]))));}
